import axiosConfig from "../axiosConfig"
export const apiDownloadFolder = async (relativePath) => {
    try {
      const response = await axiosConfig.get('/api/blastn/downloadfolder', {
        params: { path: relativePath },
        responseType: 'blob' 
      });
      const blob = new Blob([response.data], { type: 'application/zip' });
      const url = window.URL.createObjectURL(blob);
      const link = document.createElement('a');
      link.href = url;
      link.setAttribute('download', `${relativePath.split('/').pop()}.zip`);
      document.body.appendChild(link);
      link.click();
      link.remove();
      window.URL.revokeObjectURL(url);
    } catch (error) {
      throw error;
    }
  };
  
export const apiGetFolderInfo = async (relativePath) => {
  try {
    const response = await axios.get('/api/blastn/getfolderinfo', {
      params: { path: relativePath },  // Truyền đường dẫn thư mục vào API
    });
    return response.data;  // Trả về dữ liệu thư mục
  } catch (error) {
    console.error("Error fetching folder info:", error);
    throw error;  
  }
};
